INSERT INTO em_levels (level_code, title, grade_level, description, overview, total_program_days, source_file_id, source_modified, version_note, sort_order) VALUES ('EM3', 'Elevate Math Grade 3', '3', 'SVEF Elevate [Math] Curriculum, Grade 3 Summer. Students reason abstractly and quantitatively, model with mathematics while exploring changing quantities, taking wholes apart, and putting parts together.', NULL, NULL, '1U_33QQXJES-oQVnNp7hZ7Fh2ppJpQS1YC1VaXZB2VC4', '2026-03-13'::date, NULL, 0) ON CONFLICT (level_code) DO UPDATE SET title = EXCLUDED.title, grade_level = EXCLUDED.grade_level, description = EXCLUDED.description, overview = EXCLUDED.overview, total_program_days = EXCLUDED.total_program_days, updated_at = now();
INSERT INTO em_levels (level_code, title, grade_level, description, overview, total_program_days, source_file_id, source_modified, version_note, sort_order) VALUES ('EM4', 'Elevate Math Grade 4', '4', 'SVEF Elevate [Math] Curriculum, Grade 4 Summer. Students reason abstractly and quantitatively, model with mathematics while exploring changing quantities, taking wholes apart and putting parts together, discovering shape and space.', NULL, NULL, '1eslrxT1PUcKrrXhA-AKgvtugYL2sxB4LJW1fg8DrKkk', '2026-03-13'::date, NULL, 0) ON CONFLICT (level_code) DO UPDATE SET title = EXCLUDED.title, grade_level = EXCLUDED.grade_level, description = EXCLUDED.description, overview = EXCLUDED.overview, total_program_days = EXCLUDED.total_program_days, updated_at = now();
INSERT INTO em_levels (level_code, title, grade_level, description, overview, total_program_days, source_file_id, source_modified, version_note, sort_order) VALUES ('EM5', 'Elevate Math Grade 5', '5', 'SVEF Elevate [Math] Curriculum, Grade 5 Summer. Students reason abstractly and quantitatively, model with mathematics while exploring changing quantities, taking wholes apart, putting parts together, and understanding volume.', NULL, NULL, '1hmvrQSg7GyWUC1Au5ah7XvDsxkfzWH-1GwPBe-Ks4x8', '2026-04-02'::date, NULL, 0) ON CONFLICT (level_code) DO UPDATE SET title = EXCLUDED.title, grade_level = EXCLUDED.grade_level, description = EXCLUDED.description, overview = EXCLUDED.overview, total_program_days = EXCLUDED.total_program_days, updated_at = now();
INSERT INTO em_levels (level_code, title, grade_level, description, overview, total_program_days, source_file_id, source_modified, version_note, sort_order) VALUES ('EM6', 'Elevate Math Grade 6', '6', 'SVEF Elevate [Math] Curriculum, Grade 6 Summer. 19-day program covering Statistics & Data Analysis (Module 1) and Ratios & Proportional Reasoning (Module 2). Performance Tasks and Formative Assessment Lessons are central pedagogical structures.', NULL, 19, '1SENyy8y31TW_14n1UVpXVDGJOhA02JQmssmJPxXDgJA', NULL, NULL, 0) ON CONFLICT (level_code) DO UPDATE SET title = EXCLUDED.title, grade_level = EXCLUDED.grade_level, description = EXCLUDED.description, overview = EXCLUDED.overview, total_program_days = EXCLUDED.total_program_days, updated_at = now();
INSERT INTO em_levels (level_code, title, grade_level, description, overview, total_program_days, source_file_id, source_modified, version_note, sort_order) VALUES ('EM7', 'Elevate Math Grade 7', '7', 'SVEF Elevate [Math] Curriculum, Grade 7 Summer. 19-day program covering Ratios & Proportional Relationships (Module 1) and Integers & Rational Number Operations (Module 2). Performance Tasks, FAL arcs, and SERP lessons are central pedagogical structures.', NULL, 19, '1ia4k7YEsa45nka8O_G2xM7U1nPcqSjOtSWxCS9QxV50', NULL, NULL, 0) ON CONFLICT (level_code) DO UPDATE SET title = EXCLUDED.title, grade_level = EXCLUDED.grade_level, description = EXCLUDED.description, overview = EXCLUDED.overview, total_program_days = EXCLUDED.total_program_days, updated_at = now();
INSERT INTO em_levels (level_code, title, grade_level, description, overview, total_program_days, source_file_id, source_modified, version_note, sort_order) VALUES ('EM8', 'Elevate Math Grade 8', '8', 'SVEF Elevate [Math] Curriculum, Grade 8 Summer. 19-day program covering Geometric Transformations (Module 1) and Linear Equations & Algebraic Reasoning (Module 2). Uses Shell Center (SC) lesson levels and FAL arcs.', NULL, 19, '1wFcr3mRi0TuOaKUBurYSQbxMQ7TF2JNWX8XHstAL3Ws', NULL, NULL, 0) ON CONFLICT (level_code) DO UPDATE SET title = EXCLUDED.title, grade_level = EXCLUDED.grade_level, description = EXCLUDED.description, overview = EXCLUDED.overview, total_program_days = EXCLUDED.total_program_days, updated_at = now();
INSERT INTO em_levels (level_code, title, grade_level, description, overview, total_program_days, source_file_id, source_modified, version_note, sort_order) VALUES ('EM9_ALG1', 'Elevate Math Algebra 1', '9', 'SVEF Elevate [Math] Curriculum, Algebra 1 (high school version of EM9). 3-module program with Performance Task Launch-Explore-Summarize arcs, Formative Assessment Lessons (FAL), and Data Talks. Modules: Function Investigations, Model with Functions, Systems of Equations.', NULL, NULL, '1MxzLicnY_tPFBBbFag8REQ6j-J3hFHY8uqQrM2dzZaE', '2026-04-14'::date, '1 of 3 EM9 versions', 0) ON CONFLICT (level_code) DO UPDATE SET title = EXCLUDED.title, grade_level = EXCLUDED.grade_level, description = EXCLUDED.description, overview = EXCLUDED.overview, total_program_days = EXCLUDED.total_program_days, updated_at = now();
INSERT INTO em_levels (level_code, title, grade_level, description, overview, total_program_days, source_file_id, source_modified, version_note, sort_order) VALUES ('EM9_GEO', 'Elevate Math Geometry', '9', 'SVEF Elevate [Math] Curriculum, Geometry (high school version of EM9). 3-module program with Performance Task Launch-Explore-Summarize arcs, Formative Assessment Lessons (FAL), Investigations, and Data Talks. Modules: Points and Shapes, Transformations, Triangle Congruence.', NULL, NULL, '1MVbCBYzLj2i-P77h372tWw6GO2DZqhBZG-F9O-k-Z2U', '2026-04-17'::date, '2 of 3 EM9 versions', 0) ON CONFLICT (level_code) DO UPDATE SET title = EXCLUDED.title, grade_level = EXCLUDED.grade_level, description = EXCLUDED.description, overview = EXCLUDED.overview, total_program_days = EXCLUDED.total_program_days, updated_at = now();
INSERT INTO em_modules (id, level_code, parent_id, order_index, title, overview, big_ideas, standards, standards_summary, academic_vocabulary, common_misconceptions, concepts, duration_days) VALUES ('em3_m1', 'EM3', 'em3', 1, 'Multiplication and Area', 'In order to make sense of the world, students will reason abstractly and quantitatively, and model with mathematics while exploring changing quantities and taking wholes apart, putting parts together.', '["Number Flexibility to 100 for All Four Operations: Students will multiply and divide within 100 and justify answers using arrays and student generated visual representations. Encourage number sense and number flexibility - not ''blind'' memorization of number facts. Use estimation and rounding in number problems.", "Square Tiles: Students will use square tiles to measure the area of shapes, finding an area of n squared units, and learn that one square represents 1/nth of the total area."]'::jsonb, '[{"code": "3.OA.1", "text": "Interpret products of whole numbers, e.g., interpret 5 × 7 as the total number of objects in 5 groups of 7 objects each."}, {"code": "3.OA.3", "text": "Use multiplication and division within 100 to solve word problems in situations involving equal groups, arrays, and measurement quantities."}, {"code": "3.OA.4", "text": "Determine the unknown whole number in a multiplication or division equation relating three whole numbers."}, {"code": "3.OA.5", "text": "Apply properties of operations as strategies to multiply and divide (Commutative, Associative, Distributive properties)."}, {"code": "3.OA.8", "text": "Solve two-step word problems using the four operations. Represent these problems using equations with a letter standing for the unknown quantity."}, {"code": "3.MD.5.A", "text": "A square with side length 1 unit, called ''a unit square,'' is said to have ''one square unit'' of area, and can be used to measure area."}, {"code": "3.MD.7.A", "text": "Find the area of a rectangle with whole-number side lengths by tiling it, and show that the area is the same as would be found by multiplying the side lengths."}]'::jsonb, 'Represent and solve problems involving multiplication and division & Understand properties of multiplication and the relationship between multiplication and division.', '["whole numbers", "groups", "multiplication", "array", "quantities", "product", "equation", "properties", "commutative property", "associative property", "operation", "quantity", "square unit", "multiplier", "multiplicand", "unknown number"]'::jsonb, '["Confusion between multiplication sign (x) and addition (+).", "Some students confuse the terms rows and columns. Need to explicitly teach.", "When using an array to solve a multiplication problem, each row must have the same amount; each column must have the same amount.", "When using arrays to solve multiplication problems, students must neatly draw the dots/circles in rows and columns.", "Some students universally believe multiplication can be used when adding groups but each group must have the same number of objects.", "Some students may believe that 30 = 5 × 6 is written incorrectly because the product (30) must follow the equal sign.", "Better understanding of the Commutative Property and Fact Families needed (3 fours can be rotated to show that it is the same as 4 threes).", "Students think a symbol (? or []) is always the place for the answer. This is especially true when the problem is written as 15 ÷ 3 = ? or 15 = ? x 3."]'::jsonb, '["Students develop an understanding of the meanings of multiplication and division of whole numbers through activities and problems involving equal-sized groups, arrays, and area models; multiplication is finding an unknown product, and division is finding an unknown factor in these situations.", "Students recognize area as an attribute of two-dimensional regions. They measure the area of a shape by finding the total number of same-size units of area required to cover the shape without gaps or overlaps. By decomposing rectangles into rectangular arrays of squares, students connect area to multiplication."]'::jsonb, 8) ON CONFLICT (id) DO UPDATE SET level_code = EXCLUDED.level_code, title = EXCLUDED.title, overview = EXCLUDED.overview, big_ideas = EXCLUDED.big_ideas, standards = EXCLUDED.standards, standards_summary = EXCLUDED.standards_summary, academic_vocabulary = EXCLUDED.academic_vocabulary, common_misconceptions = EXCLUDED.common_misconceptions, concepts = EXCLUDED.concepts, duration_days = EXCLUDED.duration_days, updated_at = now();
INSERT INTO em_modules (id, level_code, parent_id, order_index, title, overview, big_ideas, standards, standards_summary, academic_vocabulary, common_misconceptions, concepts, duration_days) VALUES ('em3_m2', 'EM3', 'em3', 2, 'Division', 'In order to make sense of the world, students will reason abstractly and quantitatively and model with mathematics while exploring changing quantities.', '["Number flexibility to 100 for All Four Operations: Students will multiply and divide within 100 and justify answers using arrays and student generated visual representations. Encourage number sense and number flexibility - not ''blind'' memorization of number facts."]'::jsonb, '[{"code": "3.OA.1", "text": "Interpret products of whole numbers, e.g., interpret 5 × 7 as the total number of objects in 5 groups of 7 objects each."}, {"code": "3.OA.2", "text": "Interpret whole-number quotients of whole numbers, e.g., interpret 56 ÷ 8 as the number of objects in each share when 56 objects are partitioned equally into 8 shares."}, {"code": "3.OA.3", "text": "Use multiplication and division within 100 to solve word problems in situations involving equal groups, arrays, and measurement quantities."}, {"code": "3.OA.5", "text": "Apply properties of operations as strategies to multiply and divide."}]'::jsonb, 'Represent and solve problems involving multiplication and division & Understand properties of multiplication and the relationship between multiplication and division.', '["fact family", "commutative property", "equal", "partitioning", "whole", "divisor", "dividend", "division", "groups", "quotient", "share", "separate", "distribute"]'::jsonb, '["Confusion between divisor and dividend. Needs explicit teaching.", "The student sees multiplication and division as discrete and separate operations. Does not include the fact that they are linked as inverse operations.", "Students also think that 3 ÷ 15 = 5 and 15 ÷ 3 = 5 are the same equations. The use of models is essential in helping students eliminate this understanding.", "Students do not see the relationship between repeated subtraction and skip counting backwards.", "Students may assume that the commutative property also holds for division—for example, assuming that 15 ÷ 3 = 5, so 3 ÷ 15 = 5.", "Students may assume they always divide the bigger number by the smaller number."]'::jsonb, '["Students develop an understanding of the meanings of multiplication and division of whole numbers through activities and problems involving equal-sized groups, arrays, and area models; division is finding an unknown factor in these situations.", "Students use properties of operations to calculate products of whole numbers, using increasingly sophisticated strategies based on these properties to solve multiplication and division problems involving single-digit factors. By comparing a variety of solution strategies, students learn the relationship between multiplication and division."]'::jsonb, 8) ON CONFLICT (id) DO UPDATE SET level_code = EXCLUDED.level_code, title = EXCLUDED.title, overview = EXCLUDED.overview, big_ideas = EXCLUDED.big_ideas, standards = EXCLUDED.standards, standards_summary = EXCLUDED.standards_summary, academic_vocabulary = EXCLUDED.academic_vocabulary, common_misconceptions = EXCLUDED.common_misconceptions, concepts = EXCLUDED.concepts, duration_days = EXCLUDED.duration_days, updated_at = now();
INSERT INTO em_modules (id, level_code, parent_id, order_index, title, overview, big_ideas, standards, standards_summary, academic_vocabulary, common_misconceptions, concepts, duration_days) VALUES ('em4_m1', 'EM4', 'em4', 1, 'Place Value, Multiplication, and Division', 'In order to make sense of the world, students will reason abstractly and quantitatively and model with mathematics while exploring changing quantities and discovering shape and space.', '["Number and Shape Patterns: Students will generalize number and shape patterns that follow a given rule. Communicate understanding of how the pattern changes in words, symbols, and diagrams - working with multi-digit numbers.", "Factors and Area Models: Students will break numbers inside of 100 into factors. Illustrate whole-number multiplication and division calculations as area models and rectangular arrays that illustrate factors.", "Multi-Digit Numbers: Students will read and write multi-digit whole numbers in expanded form and express each number component of the expanded form as a multiple of a power of ten.", "Connected Problem Solving: Students will solve problems with perimeter, area, volume, distance, and symmetry, using operations and measurement."]'::jsonb, '[{"code": "4.NBT.1", "text": "Recognize that in a multi-digit whole number, a digit in one place represents ten times what it represents in the place to its right. For example, recognize that 700 ÷ 70 = 10 by applying concepts of place value and division."}, {"code": "4.NBT.4", "text": "Fluently add and subtract multi-digit whole numbers using the standard algorithm."}, {"code": "3.NBT.3", "text": "Multiply one-digit whole numbers by multiples of 10 in the range 10–90 (e.g., 9 × 80, 5 × 60) using strategies based on place value and properties of operations."}, {"code": "4.OA.1", "text": "Interpret a multiplication equation as a comparison, e.g., interpret 35 = 5 × 7 as a statement that 35 is 5 times as many as 7 and 7 times as many as 5. Represent verbal statements of multiplicative comparisons as multiplication equations."}, {"code": "4.OA.2", "text": "Multiply or divide to solve word problems involving multiplicative comparison, e.g., by using drawings and equations with a symbol for the unknown number to represent the problem, distinguishing multiplicative comparison from additive comparison."}]'::jsonb, 'Generalize place value understanding for multi-digit whole numbers; use place value understanding and properties of operations to perform multi-digit arithmetic.', '["place value", "digit", "ones", "tens", "hundreds", "thousands", "ten thousands", "hundred thousands", "millions", "standard form", "expanded form", "word form", "base ten form", "multiplication", "product", "factor", "division", "dividend", "divisor", "quotient", "equal groups"]'::jsonb, '["Place Value: When counting tens and ones (or hundreds, tens, and ones), the student misapplies the procedure for counting on and treats tens and ones (or hundreds, tens, and ones) as separate numbers.", "Place Value: The student recognizes simple multidigit numbers, such as thirty (30) or 400 (four hundred), but does not understand that the position of a digit determines its value.", "Place Value: The student has alternative conception of multidigit numbers and sees them as numbers independent of place value.", "Multiplication & Division: Students often treat each digit individually rather than considering its value when multiplying two-digit factors. A common mistake is to take the numbers at face value and forget about place value. This tends to occur when students are taught an algorithm without understanding the concept behind the algorithm.", "Multiplication & Division: The student may know the commutative property of multiplication but fails to apply it to simplify the work of multiplication (e.g., states 9 × 4 = 36 with relative ease, but struggles to find 4 × 9).", "Multiplication & Division: The student may know the associative property of multiplication but fails to apply it to simplify work (e.g., labors to find the product of three or more numbers like 8 × 13 × 5).", "Multiplication & Division: The student sees multiplication and division as discrete and separate operations; conception does not include the fact that they are linked as inverse operations."]'::jsonb, '["Students generalize their understanding of place value to 1,000,000, understanding the relative sizes of numbers in each place.", "They apply their understanding of models for multiplication (equal-sized groups, arrays, area models), place value, and properties of operations, in particular the distributive property, as they develop, discuss, and use efficient, accurate, and generalizable methods to compute products of multi-digit whole numbers.", "Students apply their understanding of models for division, place value, properties of operations, and the relationship of division to multiplication as they develop, discuss, and use efficient, accurate, and generalizable procedures to find quotients involving multi-digit dividends. They select and accurately apply appropriate methods to estimate and mentally calculate quotients, and interpret remainders based upon the context."]'::jsonb, 8) ON CONFLICT (id) DO UPDATE SET level_code = EXCLUDED.level_code, title = EXCLUDED.title, overview = EXCLUDED.overview, big_ideas = EXCLUDED.big_ideas, standards = EXCLUDED.standards, standards_summary = EXCLUDED.standards_summary, academic_vocabulary = EXCLUDED.academic_vocabulary, common_misconceptions = EXCLUDED.common_misconceptions, concepts = EXCLUDED.concepts, duration_days = EXCLUDED.duration_days, updated_at = now();
INSERT INTO em_modules (id, level_code, parent_id, order_index, title, overview, big_ideas, standards, standards_summary, academic_vocabulary, common_misconceptions, concepts, duration_days) VALUES ('em4_m2', 'EM4', 'em4', 2, 'Fractions and Equivalent Fractions', 'In order to make sense of the world, students will reason abstractly and quantitatively and model with mathematics while taking wholes apart, putting parts together and discovering shapes and space.', '["Fraction Flexibility: Students will understand that addition and subtraction of fractions as joining and separating parts that are referring to the same whole. Decompose fractions and mixed numbers into unit fractions and whole numbers, and express mixed numbers as a sum of unit fractions.", "Visual Fraction Models: Students will use different ways of seeing and visualizing fractions to compare fractions using student generated visual fraction models. Use >, <, and = to compare fraction size, through linear and area models, and determine whether fractions are greater or less than benchmark numbers, such as ½ and 1."]'::jsonb, '[{"code": "4.NF.A.1", "text": "Explain why a fraction a/b is equivalent to a fraction (n × a)/(n × b) by using visual fraction models, with attention to how the number and size of the parts differ even though the two fractions themselves are the same size. Use this principle to recognize and generate equivalent fractions."}, {"code": "4.NF.A.2", "text": "Compare two fractions with different numerators and different denominators, e.g., by creating common denominators or numerators, or by comparing to a benchmark fraction such as 1/2. Recognize that comparisons are valid only when the two fractions refer to the same whole. Record the results of comparisons with symbols >, =, or <, and justify the conclusions, e.g., by using a visual fraction model."}, {"code": "4.NF.B.3.C", "text": "Add and subtract mixed numbers with like denominators, e.g., by replacing each mixed number with an equivalent fraction, and/or by using properties of operations and the relationship between addition and subtraction."}, {"code": "4.NF.B.3.D", "text": "Solve word problems involving addition and subtraction of fractions referring to the same whole and having like denominators, e.g., by using visual fraction models and equations to represent the problem."}]'::jsonb, 'Extend understanding of fraction equivalence and ordering; build fractions from unit fractions; perform operations with fractions.', '["fractions", "partitions", "numerator", "denominator", "common denominators", "whole numbers", "mixed numbers", "addition", "subtraction", "equivalent", "unit fractions", "greater than", "less than", "equal to", "compare"]'::jsonb, '["Fractions: Students may not understand that fractions are equal parts of a whole. As a result, students may try to divide nontraditional shapes into equal parts the same way regular shapes are divided, or divide an object into unequal parts (equipartitioning).", "Fractions: Student writes fraction as part/part instead of part/whole.", "Fractions: Student does not understand that when finding fractions of amounts, lengths, or areas, the parts need to be equal in size.", "Fractions: Student does not understand that fractions are numbers as well as portions of a whole.", "Fractions: Student has restricted definition and thinks fractions have to be less than 1.", "Adding & Subtracting Fractions: Applying whole number concepts to fractions. Students may compare 1/4 to 1/3 and choose 1/4 as larger because four is the bigger number. They don''t yet understand that the larger the denominator, the smaller each part of the whole.", "Adding & Subtracting Fractions: When adding fractions, generalizes the procedure by adding the numerators AND the denominators (e.g., 1/4 + 1/4 = 2/8).", "Equivalent Fractions: Mistakes the fraction with the larger numerator & denominator as the larger fraction. Does not pay attention to the relationship between numerator & denominator when estimating.", "Equivalent Fractions: Restricts interpretation of fractions inappropriately and does not understand that different fractions that name the same amount are equivalent. Misapplies additive ideas when finding equivalent fractions."]'::jsonb, '["Students develop understanding of fraction equivalence and operations with fractions. They recognize that two different fractions can be equal (e.g., 15/9 = 5/3), and they develop methods for generating and recognizing equivalent fractions.", "Students extend previous understandings about how fractions are built from unit fractions, composing fractions from unit fractions, decomposing fractions into unit fractions, and using the meaning of fractions and the meaning of multiplication to multiply a fraction by a whole number."]'::jsonb, 8) ON CONFLICT (id) DO UPDATE SET level_code = EXCLUDED.level_code, title = EXCLUDED.title, overview = EXCLUDED.overview, big_ideas = EXCLUDED.big_ideas, standards = EXCLUDED.standards, standards_summary = EXCLUDED.standards_summary, academic_vocabulary = EXCLUDED.academic_vocabulary, common_misconceptions = EXCLUDED.common_misconceptions, concepts = EXCLUDED.concepts, duration_days = EXCLUDED.duration_days, updated_at = now();
INSERT INTO em_modules (id, level_code, parent_id, order_index, title, overview, big_ideas, standards, standards_summary, academic_vocabulary, common_misconceptions, concepts, duration_days) VALUES ('em5_m1', 'EM5', 'em5', 1, 'Place Value and Decimals', 'In order to make sense of the world, students will reason abstractly and quantitatively and model with mathematics while exploring changing quantities and taking wholes apart, putting parts together.', '["Modeling: Students will set up a model and use whole, fraction, and decimal numbers and operations to solve a problem. Use concrete models and drawings and justify results.", "Seeing Division: Students will solve real problems that involve volume, area, and division, setting up models and creating visual representations. Some problems should include decimal numbers. Use rounding and estimation to check accuracy and justify results.", "Powers and Place Value: Students will use whole-number exponents to represent powers of 10. Use expanded notation to write decimal numbers to the thousandths place and connect decimal notation to fractional representations, where the denominator can be expressed in powers of 10."]'::jsonb, '[{"code": "5.NBT.A.1", "text": "Recognize that in a multi-digit number, a digit in one place represents 10 times as much as it represents in the place to its right and 1/10 of what it represents in the place to its left."}, {"code": "5.NBT.A.3", "text": "Read, write, and compare decimals to thousandths."}, {"code": "5.NBT.B.7", "text": "Add, subtract, multiply, and divide decimals to hundredths, using concrete models or drawings and strategies based on place value, properties of operations, and/or the relationship between addition and subtraction; relate the strategy to a written method and explain the reasoning used."}]'::jsonb, 'Understand the place value system & Perform operations with multi-digit whole numbers and with decimals to hundredths.', '["Ones", "Tens", "Hundreds", "Thousand", "Tenths", "Hundredths", "Decimals", "Whole Number", "More Than", "Less Than", "Addition", "Subtraction", "Equal to", "Sum", "Difference", "addends"]'::jsonb, '["Place Value: Students often have an incomplete understanding of place value.", "Place Value: Students often misunderstand that the position of a number determines its value.", "Place Value: Students often focus on the digits in the number and struggle to understand the value of the number it represents.", "Decimal Numbers: Students often believe a longer decimal number is larger than a shorter decimal number.", "Decimal Numbers: Students often add or subtract without considering place value (starting at the right as with whole numbers).", "Decimal Numbers: Students tend to misplace the decimal point when adding or subtracting two decimal numbers.", "Decimal Numbers: Students often misunderstand the use of zero as a placeholder."]'::jsonb, '["Students develop understanding of why division procedures work based on the meaning of base-ten numerals and properties of operations. They finalize fluency with multi-digit addition, subtraction, multiplication, and division.", "They apply their understandings of models for decimals, decimal notation, and properties of operations to add and subtract decimals to hundredths. They develop fluency in these computations, and make reasonable estimates of their results.", "Students use the relationship between decimals and fractions, as well as the relationship between finite decimals and whole numbers, to understand and explain why the procedures for multiplying and dividing finite decimals make sense. They compute products and quotients of decimals to hundredths efficiently and accurately."]'::jsonb, 8) ON CONFLICT (id) DO UPDATE SET level_code = EXCLUDED.level_code, title = EXCLUDED.title, overview = EXCLUDED.overview, big_ideas = EXCLUDED.big_ideas, standards = EXCLUDED.standards, standards_summary = EXCLUDED.standards_summary, academic_vocabulary = EXCLUDED.academic_vocabulary, common_misconceptions = EXCLUDED.common_misconceptions, concepts = EXCLUDED.concepts, duration_days = EXCLUDED.duration_days, updated_at = now();
INSERT INTO em_modules (id, level_code, parent_id, order_index, title, overview, big_ideas, standards, standards_summary, academic_vocabulary, common_misconceptions, concepts, duration_days) VALUES ('em5_m2', 'EM5', 'em5', 2, 'Fractions and Operations with Fractions', 'In order to make sense of the world, students will reason abstractly and quantitatively and model with mathematics while exploring changing quantities and taking wholes apart, putting parts together.', '["Modeling: Students will set up a model and use whole, fraction, and decimal numbers and operations to solve a problem. Use concrete models and drawings and justify results.", "Fraction Connections: Students will make and understand visual models, to show the effect of operations on fractions. Construct line plots from real data that include fractions of units."]'::jsonb, '[{"code": "5.NF.A.1", "text": "Add and subtract fractions with unlike denominators (including mixed numbers) by replacing given fractions with equivalent fractions in such a way as to produce an equivalent sum or difference of fractions with like denominators."}, {"code": "5.NF.A.2", "text": "Solve word problems involving addition and subtraction of fractions referring to the same whole, including cases of unlike denominators, e.g., by using visual fraction models or equations to represent the problem. Use benchmark fractions and number sense to estimate mentally and assess the reasonableness of answers."}, {"code": "5.NF.B.3", "text": "Interpret a fraction as division of the numerator by the denominator (a/b = a ÷ b). Solve word problems involving division of whole numbers leading to answers in the form of fractions or mixed numbers, e.g., by using visual fraction models or equations to represent the problem."}, {"code": "5.NF.B.4", "text": "Apply and extend previous understandings of multiplication to multiply a fraction or whole number by a fraction."}, {"code": "5.NF.B.7", "text": "Apply and extend previous understandings of division to divide unit fractions by whole numbers and whole numbers by unit fractions."}]'::jsonb, 'Use equivalent fractions as a strategy to add and subtract fractions; apply and extend previous understandings of multiplication and division to multiply and divide fractions.', '["Fractions", "Unit Fractions", "Numerator", "Denominator", "Equivalent", "Decompose", "Addition", "Addends", "Compare", "Less Than", "Greater Than", "Equal To", "Subtraction", "Difference", "Multiply", "Factors", "Divide", "Quotient", "Divisor", "Product", "Dividend"]'::jsonb, '["Fractions: Students often believe that fractions must be less than 1.", "Fractions: Students count the small dividing marks (tick marks) on a number line rather than the intervals.", "Fractions: Students do not realize that when comparing the relative size of fractions, it must be assumed that all fractions refer to the same size whole.", "Fractions: Students often forget that the size of the whole makes a difference when comparing.", "Fractions: Students are often confused about the whole in complex situations.", "Fractions: Students often overgeneralize and think that ''all 1/4s are equal'' and do not understand that the size of the whole determines the size of the fractional part.", "Fractions: Overgeneralizes the idea that ''the bigger the denominator, the smaller the part'' by ignoring numerators when comparing fractions.", "Equivalent Fractions: Students often do not understand that different fractions that name the same amount are equivalent."]'::jsonb, '["Students apply their understanding of fractions and fraction models to represent the addition and subtraction of fractions with unlike denominators as equivalent calculations with like denominators. They develop fluency in calculating sums and differences of fractions.", "Students use the meaning of fractions, of multiplication and division, and the relationship between multiplication and division to understand and explain why the procedures for multiplying and dividing fractions make sense (limited to dividing unit fractions by whole numbers and whole numbers by unit fractions).", "Students develop understanding of why division procedures work based on the meaning of base-ten numerals and properties of operations. They finalize fluency with multi-digit addition, subtraction, multiplication, and division."]'::jsonb, 8) ON CONFLICT (id) DO UPDATE SET level_code = EXCLUDED.level_code, title = EXCLUDED.title, overview = EXCLUDED.overview, big_ideas = EXCLUDED.big_ideas, standards = EXCLUDED.standards, standards_summary = EXCLUDED.standards_summary, academic_vocabulary = EXCLUDED.academic_vocabulary, common_misconceptions = EXCLUDED.common_misconceptions, concepts = EXCLUDED.concepts, duration_days = EXCLUDED.duration_days, updated_at = now();
INSERT INTO em_modules (id, level_code, parent_id, order_index, title, overview, big_ideas, standards, standards_summary, academic_vocabulary, common_misconceptions, concepts, duration_days) VALUES ('em5_m3', 'EM5', 'em5', 3, 'Volume and Volume of Composite Figures', 'Understand concepts of volume and relate volume to multiplication and to addition.', '["Students recognize volume as an attribute of three-dimensional space. They understand that volume can be measured by finding the total number of same-size units of volume required to fill the space without gaps or overlaps. They understand that a 1-unit by 1-unit by 1-unit cube is the standard unit for measuring volume.", "They select appropriate units, strategies, and tools for solving problems that involve estimating and measuring volume. They decompose three-dimensional shapes and find volumes of right rectangular prisms by viewing them as decomposed into layers of arrays of cubes.", "They measure necessary attributes of shapes in order to determine volumes to solve real world and mathematical problems."]'::jsonb, '[{"code": "5.MD.3", "text": "Recognize volume as an attribute of solid figures and understand concepts of volume measurement."}, {"code": "5.MD.4", "text": "Measure volumes by counting unit cubes, using cubic cm, cubic in, cubic ft, and improvised units."}, {"code": "5.MD.5", "text": "Relate volume to the operations of multiplication and addition and solve real world and mathematical problems involving volume."}]'::jsonb, 'Geometric measurement: understand concepts of volume and relate volume to multiplication and to addition.', '["Volume", "Unit Cube", "One Cubic Unit", "Solid figures", "3 Dimensional", "Length", "Width", "Height", "Rectangular Prism", "Cube", "Base", "Formula", "composite"]'::jsonb, '["Volume: Students often have an incomplete understanding of volume as the amount of space an object takes up.", "Volume: Students may think the term ''cubic units'' only has to do with the geometric solid ''cube'' and need to understand that ''cubic units'' are used to measure any rectangular prism.", "Volume: Students may have difficulty with the concept of the formula V=l×w×h representing 3 factors (length, width, height) and may leave out one of the components.", "Volume: Students may add length, width, and height instead of multiplying them to find volume.", "Volume of Composite Figures: Students may often not understand how to correctly identify the dimensions of the individual figures that make up the composite figure.", "Volume of Composite Figures: Students may not understand they need to add the volume of the individual figures together to obtain the volume of the composite figure."]'::jsonb, '[]'::jsonb, 8) ON CONFLICT (id) DO UPDATE SET level_code = EXCLUDED.level_code, title = EXCLUDED.title, overview = EXCLUDED.overview, big_ideas = EXCLUDED.big_ideas, standards = EXCLUDED.standards, standards_summary = EXCLUDED.standards_summary, academic_vocabulary = EXCLUDED.academic_vocabulary, common_misconceptions = EXCLUDED.common_misconceptions, concepts = EXCLUDED.concepts, duration_days = EXCLUDED.duration_days, updated_at = now();
INSERT INTO em_modules (id, level_code, parent_id, order_index, title, overview, big_ideas, standards, standards_summary, academic_vocabulary, common_misconceptions, concepts, duration_days) VALUES ('em6_m1', 'EM6', 'em6', 1, 'Statistics and Data Analysis', 'Students develop understanding of statistical variability, measures of center and spread, and data displays.', '["Understand that a set of data collected to answer a statistical question has a distribution which can be described by its center, spread and overall shape.", "Recognize that a measure of center for a numerical data set summarizes all of its values with a single number, while a measure of variation describes how its values vary with a single number.", "Display numerical data in plots on a number line, including dot plots, histograms, and box plots."]'::jsonb, '[{"code": "6.SP.2", "text": "Understand that a set of data collected to answer a statistical question has a distribution which can be described by its center, spread and overall shape."}, {"code": "6.SP.3", "text": "Recognize that a measure of center for a numerical data set summarizes all of its values with a single number, while a measure of variation describes how its values vary with a single number."}, {"code": "6.SP.4", "text": "Display numerical data in plots on a number line, including dot plots, histograms, and box plots."}, {"code": "6.SP.5c", "text": "Giving quantitative measures of center [median and/or mean] and variability [interquartile range and/or mean absolute deviation], as well as describing any overall pattern and any striking deviations from the overall pattern with reference to the context in which the data were gathered."}, {"code": "6.SP.5d", "text": "Relating the choice of measures of center and variability to the shape of the data distribution and the context in which the data were gathered."}]'::jsonb, 'Develop understanding of statistical variability and summarize and describe distributions.', '["Mean", "Median", "Mode", "Range", "distribution", "data", "shape of data", "clumps", "bumps", "spaces", "outlier", "line plot", "dot plot", "bar chart", "bar graph", "histogram", "bimodal", "multimodal", "frequency"]'::jsonb, '["The mean is the only measure of center that is important or ''counts''.", "Different measures of center may be a better measure in real-world situations, e.g., real estate agents use the median to describe the market and not the mean or mode."]'::jsonb, '[]'::jsonb, 9) ON CONFLICT (id) DO UPDATE SET level_code = EXCLUDED.level_code, title = EXCLUDED.title, overview = EXCLUDED.overview, big_ideas = EXCLUDED.big_ideas, standards = EXCLUDED.standards, standards_summary = EXCLUDED.standards_summary, academic_vocabulary = EXCLUDED.academic_vocabulary, common_misconceptions = EXCLUDED.common_misconceptions, concepts = EXCLUDED.concepts, duration_days = EXCLUDED.duration_days, updated_at = now();
INSERT INTO em_modules (id, level_code, parent_id, order_index, title, overview, big_ideas, standards, standards_summary, academic_vocabulary, common_misconceptions, concepts, duration_days) VALUES ('em6_m2', 'EM6', 'em6', 2, 'Ratios and Proportional Reasoning', 'Students develop understanding of ratios, unit rates, and proportional relationships, applying them to real-world problems.', '["Understand the concept of a ratio and use ratio language to describe a ratio relationship between two quantities.", "Understand the concept of a unit rate a/b associated with a ratio a:b with b≠0, and use rate language in the context of a ratio relationship.", "Use ratio and rate reasoning to solve real-world and mathematical problems, e.g., by reasoning about tables of equivalent ratios, tape diagrams, double number line diagrams, or equations."]'::jsonb, '[{"code": "6.RP.1", "text": "Understand the concept of a ratio and use ratio language to describe a ratio relationship between two quantities."}, {"code": "6.RP.2", "text": "Understand the concept of a unit rate a/b associated with a ratio a:b with b≠0, and use rate language in the context of a ratio relationship."}, {"code": "6.RP.3", "text": "Use ratio and rate reasoning to solve real-world and mathematical problems, e.g., by reasoning about tables of equivalent ratios, tape diagrams, double number line diagrams, or equations."}]'::jsonb, 'Understand ratio concepts and use ratio reasoning to solve problems.', '["Fraction", "Numerator", "Denominator", "Quantity", "Ratio", "Rate", "Proportional", "Unit Rate", "Part/whole relationships", "part to part relationships", "equivalent ratios", "tables (horizontal/vertical)", "double number lines", "tape diagram"]'::jsonb, '["Students have confusion regarding the similarity and difference between ratios and fractions.", "Students have difficulty understanding part to part relationships."]'::jsonb, '[]'::jsonb, 9) ON CONFLICT (id) DO UPDATE SET level_code = EXCLUDED.level_code, title = EXCLUDED.title, overview = EXCLUDED.overview, big_ideas = EXCLUDED.big_ideas, standards = EXCLUDED.standards, standards_summary = EXCLUDED.standards_summary, academic_vocabulary = EXCLUDED.academic_vocabulary, common_misconceptions = EXCLUDED.common_misconceptions, concepts = EXCLUDED.concepts, duration_days = EXCLUDED.duration_days, updated_at = now();
INSERT INTO em_modules (id, level_code, parent_id, order_index, title, overview, big_ideas, standards, standards_summary, academic_vocabulary, common_misconceptions, concepts, duration_days) VALUES ('em7_m1', 'EM7', 'em7', 1, 'Ratios and Proportional Relationships', 'Students extend their understanding of ratios and develop understanding of proportionality to solve single- and multi-step problems.', '["Compute unit rates associated with ratios of fractions, including ratios of lengths, areas, and other quantities measured in like or different units.", "Recognize and represent proportional relationships between quantities. Decide whether two quantities are in a proportional relationship.", "Identify the constant of proportionality (unit rate) in tables, graphs, and verbal descriptions of proportional relationships."]'::jsonb, '[{"code": "7.RP.1", "text": "Compute unit rates associated with ratios of fractions including ratios of lengths, areas and other quantities measured in like or different units."}, {"code": "7.RP.2", "text": "Recognize and represent proportional relationships between quantities. Decide whether two quantities are in a proportional relationship. Identify the constant of proportionality (unit rate) in tables, graph, and verbal descriptions of proportional relationships."}]'::jsonb, 'Analyze proportional relationships and use them to solve real-world and mathematical problems.', '["proportional", "directly proportional", "direct variation", "proportional relationship", "unit rate", "rates", "ratio", "factors", "scale factor", "tables (horizontal/vertical)", "first quadrant graphs", "x & y axis scale"]'::jsonb, '["Students consider all linear relations to be proportional.", "Students confuse cross multiplying in proportions (equivalent fractions) with cross cancelling in multiplying fractions."]'::jsonb, '[]'::jsonb, 8) ON CONFLICT (id) DO UPDATE SET level_code = EXCLUDED.level_code, title = EXCLUDED.title, overview = EXCLUDED.overview, big_ideas = EXCLUDED.big_ideas, standards = EXCLUDED.standards, standards_summary = EXCLUDED.standards_summary, academic_vocabulary = EXCLUDED.academic_vocabulary, common_misconceptions = EXCLUDED.common_misconceptions, concepts = EXCLUDED.concepts, duration_days = EXCLUDED.duration_days, updated_at = now();
INSERT INTO em_modules (id, level_code, parent_id, order_index, title, overview, big_ideas, standards, standards_summary, academic_vocabulary, common_misconceptions, concepts, duration_days) VALUES ('em7_m2', 'EM7', 'em7', 2, 'Integers and Rational Number Operations', 'Students apply and extend previous understandings of operations with fractions to add, subtract, multiply, and divide rational numbers.', '["Apply and extend previous understandings of addition and subtraction to add and subtract rational numbers; represent addition and subtraction on a horizontal or vertical number line diagram.", "Understand p+q as the number located a distance absolute value q from p, in the positive or negative direction depending on whether q is positive or negative.", "Show that a number and its opposite have a sum of 0 (are additive inverses); interpret sums of rational numbers by describing real-world contexts.", "Understand subtraction of rational numbers as adding the additive inverse, p−q = p+(−q). Show that the distance between two rational numbers on the number line is the absolute value of their difference."]'::jsonb, '[{"code": "7.NS.1", "text": "Apply and extend previous understandings of addition and subtraction to add, subtract, rational numbers; represent addition and subtraction on a horizontal or vertical number line diagram."}, {"code": "7.NS.1.b", "text": "Understand p+q as the number located a distance absolute value q from p, in the positive or negative direction depending on whether q is positive or negative. Show that a number and its opposite have a sum of 0 (are additive inverses) interpret sums of rational numbers by describing real-world contexts."}, {"code": "7.NS.1.c", "text": "Understand subtraction of rational numbers as adding the additive inverse, p+q = p+(-q). Show that the distance between two rational numbers on the number line is the absolute value of their difference, and apply this principle in real-world contexts."}]'::jsonb, 'Apply and extend previous understandings of operations with fractions to add, subtract, multiply, and divide rational numbers.', '["counting numbers", "whole numbers", "integer", "rational numbers", "negative", "positive", "horizontal", "vertical", "absolute value", "distance on a vertical or horizontal number line", "greater than", "less than", "thermometer"]'::jsonb, '["A narrow understanding of integer operations — procedural at best.", "Thinking that integer operations can only be done in one way."]'::jsonb, '[]'::jsonb, 9) ON CONFLICT (id) DO UPDATE SET level_code = EXCLUDED.level_code, title = EXCLUDED.title, overview = EXCLUDED.overview, big_ideas = EXCLUDED.big_ideas, standards = EXCLUDED.standards, standards_summary = EXCLUDED.standards_summary, academic_vocabulary = EXCLUDED.academic_vocabulary, common_misconceptions = EXCLUDED.common_misconceptions, concepts = EXCLUDED.concepts, duration_days = EXCLUDED.duration_days, updated_at = now();
INSERT INTO em_modules (id, level_code, parent_id, order_index, title, overview, big_ideas, standards, standards_summary, academic_vocabulary, common_misconceptions, concepts, duration_days) VALUES ('em8_m1', 'EM8', 'em8', 1, 'Geometric Transformations', 'Students verify properties of rigid transformations and dilations, understand congruence through transformations, and describe effects of transformations using coordinates.', '["Verify experimentally the properties of rotations, reflections, and translations: lines are taken to lines and line segments to line segments of the same length; angles are taken to angles of the same measure; parallel lines are taken to parallel lines.", "Understand that a two-dimensional figure is congruent to another if the second can be obtained from the first by a sequence of rotations, reflections, and translations; given two congruent figures, describe a sequence that exhibits the congruence between them.", "Describe the effect of dilations, translations, rotations, and reflections on two-dimensional figures using coordinates."]'::jsonb, '[{"code": "8.G.1", "text": "Verify experimentally the properties of rotations, reflections, and translations: lines are taken to lines and line segments to line segments of the same length; angles are taken to angles of the same measure; parallel lines are taken to parallel lines."}, {"code": "8.G.2", "text": "Understand that a two-dimensional figure is congruent to another if the second can be obtained from the first by a sequence of rotations, reflections, and translations; given two congruent figures, describe a sequence that exhibits the congruence between them."}, {"code": "8.G.3", "text": "Describe the effect of dilations, translations, rotations, and reflections on two-dimensional figures using coordinates."}]'::jsonb, 'Understand congruence and similarity using physical models, transparencies, or geometry software.', '["rigid motion transformation", "transformations", "translations", "reflections", "rotations", "dilations", "Cartesian Plane", "horizontal", "vertical", "symmetry", "rotational symmetry", "line of reflection", "line of symmetry", "ordered pair", "corresponding points", "clockwise", "counter-clockwise"]'::jsonb, '["Students tend to believe that a point of rotation is always on the shape rather than considering a point of rotation could be in the plane outside of the shape.", "Students tend to ignore the center of rotation and rotate instead from a corner of the figure.", "Reflection issues: Reflect on x-axis or y-axis instead of the line of reflection.", "Reflection issues: Struggle when line of reflection is not horizontal or vertical.", "Confusion of terms: Horizontal and vertical; Reflect and Rotate; Translate instead of reflect; Translations and transformations; Clockwise and counterclockwise; Rotation vs. Reflection.", "X and y coordinate confusion.", "Negative dilation vs. fractional dilation.", "Students think the shape should move to a different quadrant after it is transformed."]'::jsonb, '[]'::jsonb, 10) ON CONFLICT (id) DO UPDATE SET level_code = EXCLUDED.level_code, title = EXCLUDED.title, overview = EXCLUDED.overview, big_ideas = EXCLUDED.big_ideas, standards = EXCLUDED.standards, standards_summary = EXCLUDED.standards_summary, academic_vocabulary = EXCLUDED.academic_vocabulary, common_misconceptions = EXCLUDED.common_misconceptions, concepts = EXCLUDED.concepts, duration_days = EXCLUDED.duration_days, updated_at = now();
INSERT INTO em_modules (id, level_code, parent_id, order_index, title, overview, big_ideas, standards, standards_summary, academic_vocabulary, common_misconceptions, concepts, duration_days) VALUES ('em8_m2', 'EM8', 'em8', 2, 'Linear Equations and Algebraic Reasoning', 'Students analyze slope and intercepts and solve linear equations including pairs of simultaneous linear equations through graphing and tables and using technology. They move between different representations of linear functions.', '["Linear Equations: Analyze slope and intercepts and solve linear equations including pairs of simultaneous linear equations through graphing and tables and using technology.", "Multiple Representations of Functions: Move between different representations of linear functions (i.e., equation, graph, table, and context), sketch and analyze graphs, use similar triangles to visualize slope and rate of change with equations containing rational number coefficients."]'::jsonb, '[{"code": "8.EE.7", "text": "Solve linear equations in one variable. Give examples of linear equations in one variable with one solution, infinitely many solutions, or no solutions. Show which of these possibilities is the case by successively transforming the given equation into simpler forms, until an equivalent equation of the form x = a, a = a, or a = b results (where a and b are different numbers)."}]'::jsonb, 'Analyze and solve linear equations and pairs of simultaneous linear equations.', '["expression", "like terms", "balance", "equation", "equality", "equivalent expressions", "unknowns", "field axioms (commutativity, distributivity, identity elements)", "order of operations", "parenthesis", "exponents", "solution (one solution, no solution, infinitely many solutions)"]'::jsonb, '["Students consider that there is just one ''correct'' expression.", "Students consider that in an equation, there is an answer and an expression only rather than two equivalent expressions.", "Students assume an answer of 0 and no solution are the same.", "Students assume often times that if there are parenthesis in an expression that this expression must represent only the distributive property."]'::jsonb, '["The eighth grade domain ''Expressions and Equations'' addresses the concepts of variables, constraints, and equality in real world context. Quantities express relationships between variables and given constraints with symbolism such as the mathematical operations, parentheses, variables, and constants.", "Equations express an equivalent relationship between two quantities (expressions). To solve an equation means to find values of the variable(s) that make the equation true.", "Algebraic methods of altering linear equation using the distributive property and collecting like-terms, may be used to solve an equation.", "Linear equations are a specific type of equation and may be represented graphically by a line. One formula for a linear equation in two variables, y = mx+b, highlights the slope of that line with the variable m, while x and y represent input and output variables and b represents where the line crosses the y-axis on the graph.", "A linear equation in two variables has an infinite number of solution sets or pairs of x and y values which make the equation true. A linear equation in one variable may have one, no, or infinitely many solutions. If an equation has no solutions then it is not a true statement of equivalence for any values. If an equation is true regardless of what values are substituted for any variables then it has infinite solutions and is called an ''identity.''"]'::jsonb, 9) ON CONFLICT (id) DO UPDATE SET level_code = EXCLUDED.level_code, title = EXCLUDED.title, overview = EXCLUDED.overview, big_ideas = EXCLUDED.big_ideas, standards = EXCLUDED.standards, standards_summary = EXCLUDED.standards_summary, academic_vocabulary = EXCLUDED.academic_vocabulary, common_misconceptions = EXCLUDED.common_misconceptions, concepts = EXCLUDED.concepts, duration_days = EXCLUDED.duration_days, updated_at = now();
INSERT INTO em_modules (id, level_code, parent_id, order_index, title, overview, big_ideas, standards, standards_summary, academic_vocabulary, common_misconceptions, concepts, duration_days) VALUES ('em9a1_m1', 'EM9_ALG1', 'em9_algebra1', 1, 'Function Investigations', 'Students investigate data sets by table and graph and using technology; they fit and interpret functions to model the data between two quantities.', '["Function Investigations: Students investigate data sets by table and graph and using technology; they fit and interpret functions to model the data between two quantities. Students interpret information from the functions, noticing key features and symmetries. Students develop understanding of the meaning of the function and how it represents the data that it is modeling."]'::jsonb, '[{"code": "F-IF", "text": "Interpret functions that arise in applications in terms of the context. Analyze functions using different representations."}, {"code": "F-BF", "text": "Build a function that models a relationship between two quantities."}, {"code": "F-LE", "text": "Construct linear models and solve problems."}]'::jsonb, 'Interpret functions arising in applications; analyze functions using different representations; build linear models.', '["slope", "intercepts", "linear relationship", "linear function", "ordered pair", "t-table (table of values)", "rate of change", "increasing", "decreasing"]'::jsonb, '["Interchanging meanings: Believing the slope represents where the line crosses the y-axis (y-intercept) and vice versa.", "Interpreting slope direction: Not understanding that a positive slope indicates an increasing line, while a negative slope indicates a decreasing line.", "Graphing and interpreting: Assuming the line must go through the origin — thinking that every linear function must pass through the point (0, 0).", "Misreading the scale: Incorrectly interpreting the values on the x and y axes when plotting points.", "Not recognizing constant rate of change: Failing to understand that the slope represents a constant change in y for every change in x.", "Variable confusion: Thinking that the variable in the equation always represents the x-coordinate.", "Not identifying linear relationships: Failing to recognize situations in real life that can be modeled by a linear function.", "Extrapolation errors: Making unreasonable predictions beyond the data range of a linear model.", "Distance v Time errors: A steep line means the object is at a higher elevation; a horizontal line means the object is moving slowly; a downward-sloping line means the object is slowing down; a straight diagonal line means the object is speeding up."]'::jsonb, '["Focus on graph shape and what it represents, how the quantities change over time, multiple representations of the same function"]'::jsonb, 6) ON CONFLICT (id) DO UPDATE SET level_code = EXCLUDED.level_code, title = EXCLUDED.title, overview = EXCLUDED.overview, big_ideas = EXCLUDED.big_ideas, standards = EXCLUDED.standards, standards_summary = EXCLUDED.standards_summary, academic_vocabulary = EXCLUDED.academic_vocabulary, common_misconceptions = EXCLUDED.common_misconceptions, concepts = EXCLUDED.concepts, duration_days = EXCLUDED.duration_days, updated_at = now();
INSERT INTO em_modules (id, level_code, parent_id, order_index, title, overview, big_ideas, standards, standards_summary, academic_vocabulary, common_misconceptions, concepts, duration_days) VALUES ('em9a1_m2', 'EM9_ALG1', 'em9_algebra1', 2, 'Model with Functions', 'Students will investigate data sets by table and graph, and fit and interpret functions to model data between two quantities. Students will interpret information from functions and notice key features and symmetries.', '["Model with Functions: Students will investigate data sets by table and graph, and fit and interpret functions to model data between two quantities. Students will interpret information from functions and notice key features and symmetries. Students will develop understanding of the meaning of the function and how it represents the data that it is modeling."]'::jsonb, '[{"code": "F-IF", "text": "Interpret functions that arise in applications in terms of the context. Analyze functions using different representations."}, {"code": "F-BF", "text": "Build a function that models a relationship between two quantities."}, {"code": "F-LE", "text": "Construct linear models and solve problems."}]'::jsonb, 'Interpret functions arising in applications; analyze functions using different representations; build linear models.', '["linear function", "intercepts", "slope", "increasing or decreasing", "positive or negative"]'::jsonb, '["Interpreting the linear model: Not recognizing when a real-world situation is not accurately modeled by a linear equation.", "Assuming the linear model applies to extreme values outside the data range.", "Failing to understand that the y-intercept represents a starting point in a real-world context.", "Algebraic manipulation: Making errors in calculating slope using the formula (change in y / change in x).", "Incorrectly substituting values into a linear equation to find a solution.", "Not properly interpreting negative values in the equation.", "Real-world application: Choosing the wrong variables to represent quantities in a problem.", "Not considering units when interpreting the slope and y-intercept.", "Assuming a linear relationship exists between two variables without analyzing the data first.", "Extrapolation errors: Making unreasonable predictions beyond the data range of a linear model."]'::jsonb, '["Focus on how a mathematical statement or equation can represent the quantities in a given context. Students explore multiple representations of the same function."]'::jsonb, 6) ON CONFLICT (id) DO UPDATE SET level_code = EXCLUDED.level_code, title = EXCLUDED.title, overview = EXCLUDED.overview, big_ideas = EXCLUDED.big_ideas, standards = EXCLUDED.standards, standards_summary = EXCLUDED.standards_summary, academic_vocabulary = EXCLUDED.academic_vocabulary, common_misconceptions = EXCLUDED.common_misconceptions, concepts = EXCLUDED.concepts, duration_days = EXCLUDED.duration_days, updated_at = now();
INSERT INTO em_modules (id, level_code, parent_id, order_index, title, overview, big_ideas, standards, standards_summary, academic_vocabulary, common_misconceptions, concepts, duration_days) VALUES ('em9a1_m3', 'EM9_ALG1', 'em9_algebra1', 3, 'Systems of Equations', 'Students investigate real situations that include data for which systems of 1 or 2 equations are helpful, paying attention to units. Students use technology tools strategically to find their solutions and approximate solutions.', '["Systems of Equations: Students investigate real situations that include data for which systems of 1 or 2 equations are helpful, paying attention to units. Students use technology tools strategically to find their solutions and approximate solutions, constructing viable arguments, interpreting the meaning of the results, and communicating them in multidimensional ways."]'::jsonb, '[{"code": "A-REI", "text": "Solve equations in one variable. Solve systems of equations. Represent and solve equations graphically."}, {"code": "A-SSE", "text": "Interpret the structure of expressions."}, {"code": "F-LE", "text": "Construct linear models and solve problems."}]'::jsonb, 'Solve equations in one variable; solve systems of equations; represent and solve equations graphically.', '["system of equations", "solution to a system of equations", "ordered pair", "intersect", "variable"]'::jsonb, '["Thinking a system always has one solution: Students might assume that every system of equations will have a single solution point, not realizing that parallel lines (no solution) or identical lines (infinite solutions) can occur.", "Misinterpreting the graph intersection: Not understanding that the point where two lines intersect on a graph represents the solution to the system of equations.", "Solving only one equation: Attempting to solve a system of equations by manipulating only one of the equations, ignoring the need to find a solution that satisfies both equations simultaneously.", "Incorrect substitution: When using the substitution method, substituting incorrectly by not isolating a variable properly in one equation before plugging it into the other.", "Not checking for extraneous solutions: Failing to check if the solution obtained actually satisfies both original equations, which can lead to including extraneous solutions.", "Confusing slope and y-intercept: When graphing lines, mixing up the values of the slope and y-intercept, leading to incorrect line placement.", "Not understanding the concept of elimination: When using the elimination method, not properly manipulating equations to eliminate one variable, leading to incorrect calculations."]'::jsonb, '["Focus on graph shape and what it represents, how the quantities change over time, multiple representations of the same function"]'::jsonb, 6) ON CONFLICT (id) DO UPDATE SET level_code = EXCLUDED.level_code, title = EXCLUDED.title, overview = EXCLUDED.overview, big_ideas = EXCLUDED.big_ideas, standards = EXCLUDED.standards, standards_summary = EXCLUDED.standards_summary, academic_vocabulary = EXCLUDED.academic_vocabulary, common_misconceptions = EXCLUDED.common_misconceptions, concepts = EXCLUDED.concepts, duration_days = EXCLUDED.duration_days, updated_at = now();
INSERT INTO em_modules (id, level_code, parent_id, order_index, title, overview, big_ideas, standards, standards_summary, academic_vocabulary, common_misconceptions, concepts, duration_days) VALUES ('em9geo_m1', 'EM9_GEO', 'em9_geometry', 1, 'Points and Shapes', 'Solve problems involving geometric shapes in the coordinate plane using dynamic geometric software to apply the distance formula, Pythagorean Theorem, and slope in solving problems. Find areas and perimeters of triangles and rectangles in the coordinate plane.', '["Points and Shapes: Solve problems involving geometric shapes in the coordinate plane using dynamic geometric software to apply the distance formula, Pythagorean Theorem, and slope in solving problems. Find areas and perimeters of triangles and rectangles in the coordinate plane."]'::jsonb, '[{"code": "G-GPE", "text": "Use coordinates to prove simple geometric theorems algebraically."}]'::jsonb, 'Use coordinates to prove simple geometric theorems algebraically.', '["coordinate plane", "ordered pair", "slope", "perimeter", "area", "hypotenuse"]'::jsonb, '["Confusing (x, y) Order — Students sometimes reverse the x- and y-coordinates when plotting points.", "Dropping the Square Root — Students might forget to take the square root at the end of the distance formula calculation or to find a missing value in the Pythagorean Theorem.", "Mixing Up Components of Distance Formula and Pythagorean Theorem — Not recognizing when to apply the appropriate method based on problem context and given information.", "Thinking Parallel Lines Have the Same Y-Intercept — Assuming that all parallel lines overlap instead of just having the same slope.", "Flipping Signs for Perpendicular Slopes — Knowing perpendicular slopes are negative reciprocals but incorrectly applying the negative sign."]'::jsonb, '["Focus on the Pythagorean Theorem and how to utilize Pythagorean Theorem to calculate distance on a coordinate plane, including finding areas and perimeters."]'::jsonb, 7) ON CONFLICT (id) DO UPDATE SET level_code = EXCLUDED.level_code, title = EXCLUDED.title, overview = EXCLUDED.overview, big_ideas = EXCLUDED.big_ideas, standards = EXCLUDED.standards, standards_summary = EXCLUDED.standards_summary, academic_vocabulary = EXCLUDED.academic_vocabulary, common_misconceptions = EXCLUDED.common_misconceptions, concepts = EXCLUDED.concepts, duration_days = EXCLUDED.duration_days, updated_at = now();
INSERT INTO em_modules (id, level_code, parent_id, order_index, title, overview, big_ideas, standards, standards_summary, academic_vocabulary, common_misconceptions, concepts, duration_days) VALUES ('em9geo_m2', 'EM9_GEO', 'em9_geometry', 2, 'Transformations', 'Understand rotations, reflections, and translations of regular polygons, quadrilaterals, angles, and line segments. Identify transformations, through investigation, that move a figure back onto itself, using that process to prove congruence.', '["Transformations: Understand rotations, reflections, and translations of regular polygons, quadrilaterals, angles, and line segments. Identify transformations, through investigation, that move a figure back onto itself, using that process to prove congruence."]'::jsonb, '[{"code": "G-CO", "text": "Experiment with transformations in the plane."}]'::jsonb, 'Experiment with transformations in the plane.', '["transformation", "rigid motion", "translation", "reflection", "rotation", "preimage", "image", "congruence"]'::jsonb, '["Thinking Transformations Change Shape or Size — Some students believe that translations, reflections, and rotations distort figures, rather than preserving their size and angles.", "Confusing Different Transformations — Students may mix up translations, reflections, and rotations, especially when transformations are combined.", "Not Understanding the Direction of Rotations — Many students struggle with counterclockwise (positive) and clockwise (negative) rotation conventions.", "Assuming All Rotations Are About the Origin — Some students forget that rotations can happen around any point, not just (0,0).", "Forgetting the Line of Reflection — Students may think that reflecting over a line just flips the shape without considering equal distance from the line.", "Incorrectly Applying Coordinate Rules — Students often struggle with the formulas for reflections and rotations (e.g., reflecting over the y-axis should negate the x-coordinate).", "Forgetting to Apply the Same Transformation to All Points — Some students only transform part of a figure instead of every point.", "Not Keeping Track of Preimage and Image — Students may confuse which shape is the original (preimage) and which is the transformed (image)."]'::jsonb, '["Focus on the criteria for each rigid motion transformation and begin to discuss how rigid motion transformations prove congruence."]'::jsonb, 7) ON CONFLICT (id) DO UPDATE SET level_code = EXCLUDED.level_code, title = EXCLUDED.title, overview = EXCLUDED.overview, big_ideas = EXCLUDED.big_ideas, standards = EXCLUDED.standards, standards_summary = EXCLUDED.standards_summary, academic_vocabulary = EXCLUDED.academic_vocabulary, common_misconceptions = EXCLUDED.common_misconceptions, concepts = EXCLUDED.concepts, duration_days = EXCLUDED.duration_days, updated_at = now();
INSERT INTO em_modules (id, level_code, parent_id, order_index, title, overview, big_ideas, standards, standards_summary, academic_vocabulary, common_misconceptions, concepts, duration_days) VALUES ('em9geo_m3', 'EM9_GEO', 'em9_geometry', 3, 'Triangle Congruence', 'Investigate triangles and their congruence over rigid transformations verifying findings using triangle congruence theorems (ASA, SSS, SAS, AAS, and HL) and other geometric properties, including vertical angles, angles created by transversals across parallel lines, and bisectors.', '["Triangle Congruence: Investigate triangles and their congruence over rigid transformations verifying findings using triangle congruence theorems (ASA, SSS, SAS, AAS, and HL) and other geometric properties, including vertical angles, angles created by transversals across parallel lines, and bisectors."]'::jsonb, '[{"code": "G-CO", "text": "Understand congruence in terms of rigid motions."}]'::jsonb, 'Understand congruence in terms of rigid motions.', '["congruent triangles", "rigid motion transformation", "corresponding angles", "corresponding sides", "right triangle"]'::jsonb, '["Thinking SSA (Side-Side-Angle) Proves Congruence — Students often mistakenly believe that SSA is a valid triangle congruence theorem, but it does not always guarantee congruence.", "Confusing AAS and ASA — Students sometimes mix up Angle-Angle-Side (AAS) and Angle-Side-Angle (ASA), not realizing that ASA requires the included side.", "Believing AAA Proves Congruence — Students may assume that if two triangles have equal angles, they must be congruent, forgetting that AAA only proves similarity, not congruence.", "Thinking HL Applies to All Triangles — Some students mistakenly try to use the Hypotenuse-Leg (HL) theorem for non-right triangles.", "Believing Figures Must Be Oriented the Same Way to Be Congruent — Some students think two triangles must have the same orientation to be congruent, not recognizing that transformations can reposition them."]'::jsonb, '["Focus on the different ways to show triangle congruence (rigid motion, congruence theorems)."]'::jsonb, 6) ON CONFLICT (id) DO UPDATE SET level_code = EXCLUDED.level_code, title = EXCLUDED.title, overview = EXCLUDED.overview, big_ideas = EXCLUDED.big_ideas, standards = EXCLUDED.standards, standards_summary = EXCLUDED.standards_summary, academic_vocabulary = EXCLUDED.academic_vocabulary, common_misconceptions = EXCLUDED.common_misconceptions, concepts = EXCLUDED.concepts, duration_days = EXCLUDED.duration_days, updated_at = now();
